   "why": "得 = “được, thu về”, 到 = “tới nơi”: kết quả đạt được. 收 = “thu về từ tay người gửi”. Tâm lý: nói 得到 khi bạn muốn nhấn mạnh công sức; 收到 khi bạn xác nhận “đã tới tay mình”.",
